DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND q.stimulus=$batch01$It is now clear that the ancient Egyptians were the first society to produce alcoholic beverages. It had been thought that the ancient Babylonians were the first; they had mastered the process of fermentation for making wine as early as 1500 B.C. However, archaeologists have discovered an Egyptian cup dating from 2000 B.C. whose sides depict what appears to be an Egyptian brewery, and whose chemical residue reveals that it contained a form of alcoholic beer.$batch01$ AND q.prompt=$batch01$The reasoning above is most vulnerable to criticism on which one of the following grounds?$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT119-S2-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND e.style IN ('single','standard')) <> 1 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S2-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It makes a generalization about Egyptian society based on a sample so small that it is likely to be unrepresentative.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S2-Q24 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It uses the term “alcoholic beverage” in a different sense in the premises than in the conclusion.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S2-Q24 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It presumes, without providing justification, that because one society developed a technology before another, the development in the latter was dependent on the development in the former.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S2-Q24 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It ignores the possibility that the first known instance of a kind is not the first instance of that kind.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S2-Q24 D'; END IF; END $guard$;
